  const getNextLaudoNumber = async (): Promise<number> => {
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/laudo_config?id=eq.config&select=ultimo_numero`, {
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });
      if (!res.ok) throw new Error('Erro ao obter sequência de laudos');
      const json = await res.json();
      const currentSeq = json && json[0] ? json[0].ultimo_numero : 0;
      return currentSeq + 1;
    } catch (error) {
      console.error('Erro ao gerar sequenciamento automático de laudo:', error);
      return Math.floor(10000 + Math.random() * 90000);
    }
  };

  const handleOpenCreateLaudo = async () => {
    const today = new Date();
    const offset = today.getTimezoneOffset();
    const localToday = new Date(today.getTime() - (offset * 60 * 1000));
    const nowStr = localToday.toISOString().slice(0, 16); // format: "YYYY-MM-DDTHH:mm"
    const dateStr = localToday.toISOString().slice(0, 10); // format: "YYYY-MM-DD"

    setFormLaudoNumero('Gerando...');
    getNextLaudoNumber().then(num => setFormLaudoNumero(num));

    setFormLaudoData(dateStr);
    setFormLaudoEntrada(nowStr);
    setFormLaudoSaida(nowStr);
    setFormLaudoPlacaCavalo('');
    setFormLaudoPlacaCarreta1('');
    setFormLaudoPlacaCarreta2('');
    setFormLaudoEmpresa('');
    setFormLaudoFrota('');
    setFormLaudoModelo('');

    setFormLaudoCavaloInterno(false);
    setFormLaudoCavaloInternoSoprar(false);
    setFormLaudoCavaloInternoAspirar(false);
    setFormLaudoCavaloInternoHidratacao(false);
    setFormLaudoCavaloInternoMotor(false);
    setFormLaudoCavaloExterno(false);
    setFormLaudoCavaloExternoAguaQuente(false);
    setFormLaudoCavaloExternoAguaFria(false);
    setFormLaudoCavaloCera(false);

    setFormLaudoCarretaInterno(false);
    setFormLaudoCarretaInternoAguaQuente(false);
    setFormLaudoCarretaInternoAguaFria(false);
    setFormLaudoCarretaExterno(false);
    setFormLaudoCarretaExternoAguaQuente(false);
    setFormLaudoCarretaExternoAguaFria(false);
    setFormLaudoCarretaExternoJatoAgua(false);
    setFormLaudoCarretaExternoBocaSuperior(false);
    setFormLaudoCarretaExternoBocaLateral(false);
    setFormLaudoCarretaExternoEmbaixo(false);
    setFormLaudoCarretaExternoMangote(false);
    setFormLaudoCarretaExternoLona(false);

    setFormLaudoSecagemManualFunc('');
    setFormLaudoNomeMotorista('');
    setFormLaudoLavadorNome('');
    setFormLaudoLacres(Array(10).fill(''));
    setFormLaudoUltimasCargas(Array(3).fill(''));
    setFormLaudoObservacoes('');

    setFormLaudoError(null);
    setSelectedLaudo(null);
    setLaudoFormMode('create');
  };

  const handleOpenEditLaudo = (laudo: LaudoHigienizacao) => {
    setSelectedLaudo(laudo);
    setFormLaudoNumero(laudo.numero_laudo);
    setFormLaudoData(laudo.data_laudo ? laudo.data_laudo.slice(0, 10) : '');
    setFormLaudoEntrada(laudo.entrada_data_hora ? laudo.entrada_data_hora.slice(0, 16) : '');
    setFormLaudoSaida(laudo.saida_data_hora ? laudo.saida_data_hora.slice(0, 16) : '');
    setFormLaudoPlacaCavalo(laudo.placa_cavalo || '');
    setFormLaudoPlacaCarreta1(laudo.placa_carreta_1 || '');
    setFormLaudoPlacaCarreta2(laudo.placa_carreta_2 || '');
    setFormLaudoEmpresa(laudo.empresa || '');
    setFormLaudoFrota(laudo.frota || '');
    setFormLaudoModelo(laudo.modelo || '');

    setFormLaudoCavaloInterno(!!laudo.cavalo_interno);
    setFormLaudoCavaloInternoSoprar(!!laudo.cavalo_interno_soprar);
    setFormLaudoCavaloInternoAspirar(!!laudo.cavalo_interno_aspirar);
    setFormLaudoCavaloInternoHidratacao(!!laudo.cavalo_interno_hidratacao);
    setFormLaudoCavaloInternoMotor(!!laudo.cavalo_interno_motor);
    setFormLaudoCavaloExterno(!!laudo.cavalo_externo);
    setFormLaudoCavaloExternoAguaQuente(!!laudo.cavalo_externo_agua_quente);
    setFormLaudoCavaloExternoAguaFria(!!laudo.cavalo_externo_agua_fria);
    setFormLaudoCavaloCera(!!laudo.cavalo_cera);

    setFormLaudoCarretaInterno(!!laudo.carreta_interno);
    setFormLaudoCarretaInternoAguaQuente(!!laudo.carreta_interno_agua_quente);
    setFormLaudoCarretaInternoAguaFria(!!laudo.carreta_interno_agua_fria);
    setFormLaudoCarretaExterno(!!laudo.carreta_externo);
    setFormLaudoCarretaExternoAguaQuente(!!laudo.carreta_externo_agua_quente);
    setFormLaudoCarretaExternoAguaFria(!!laudo.carreta_externo_agua_fria);
    setFormLaudoCarretaExternoJatoAgua(!!laudo.carreta_externo_jato_agua);
    setFormLaudoCarretaExternoBocaSuperior(!!laudo.carreta_externo_boca_superior);
    setFormLaudoCarretaExternoBocaLateral(!!laudo.carreta_externo_boca_lateral);
    setFormLaudoCarretaExternoEmbaixo(!!laudo.carreta_externo_embaixo);
    const isMangote = !!(
      laudo.carreta_externo_mangote ||
      (laudo as any).carreta_externoMangote ||
      (laudo as any).carreta_mangote ||
      (laudo.observacoes && laudo.observacoes.includes('[MANGOTE:SIM]'))
    );
    setFormLaudoCarretaExternoMangote(isMangote);
    setFormLaudoCarretaExternoLona(!!laudo.carreta_externo_lona);

    setFormLaudoSecagemManualFunc(laudo.secagem_manual_funcionario || '');
    setFormLaudoNomeMotorista(laudo.nome_motorista || '');
    setFormLaudoLavadorNome(laudo.lavador_nome || '');

    const lacresArray = Array(10).fill('');
    if (laudo.lacres) {
      laudo.lacres.forEach((l, idx) => { if (idx < 10) lacresArray[idx] = l; });
    }
    setFormLaudoLacres(lacresArray);

    const cargasArray = Array(3).fill('');
    if (laudo.ultimas_cargas) {
      laudo.ultimas_cargas.forEach((c, idx) => { if (idx < 3) cargasArray[idx] = c; });
    }
    setFormLaudoUltimasCargas(cargasArray);

    const cleanObs = (laudo.observacoes || '').replace(/\[MANGOTE:SIM\]/g, '').trim();
    setFormLaudoObservacoes(cleanObs);
    setFormLaudoError(null);
    setLaudoFormMode('edit');
  };

  const handleSaveLaudo = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormLaudoSubmitting(true);
    setFormLaudoError(null);

    try {
      if (!formLaudoPlacaCavalo) {
        throw new Error('A placa do cavalo é obrigatória.');
      }

      let numeroLaudoToSave: number;
      if (laudoFormMode === 'create') {
        numeroLaudoToSave = await getNextLaudoNumber();
      } else {
        numeroLaudoToSave = Number(formLaudoNumero);
      }

      if (isNaN(numeroLaudoToSave)) {
        throw new Error('Número do laudo inválido.');
      }

      const cleanLacres = formLaudoLacres.map(x => x.trim()).filter(Boolean);
      const cleanCargas = formLaudoUltimasCargas.map(x => x.trim()).filter(Boolean);

      const cleanUserObs = (formLaudoObservacoes || '').replace(/\[MANGOTE:SIM\]/g, '').trim();
      const finalObs = formLaudoCarretaExternoMangote
        ? (cleanUserObs ? `${cleanUserObs}\n[MANGOTE:SIM]` : '[MANGOTE:SIM]')
        : (cleanUserObs || null);

      const payload: any = {
        numero_laudo: numeroLaudoToSave,
        data_laudo: formLaudoData,
        entrada_data_hora: formLaudoEntrada ? new Date(formLaudoEntrada).toISOString() : null,
        saida_data_hora: formLaudoSaida ? new Date(formLaudoSaida).toISOString() : null,
        placa_cavalo: formLaudoPlacaCavalo.toUpperCase(),
        placa_carreta_1: formLaudoPlacaCarreta1.toUpperCase() || null,
        placa_carreta_2: formLaudoPlacaCarreta2.toUpperCase() || null,
        empresa: formLaudoEmpresa || null,
        frota: formLaudoFrota || null,
        modelo: formLaudoModelo || null,

        cavalo_interno: formLaudoCavaloInterno,
        cavalo_interno_soprar: formLaudoCavaloInternoSoprar,
        cavalo_interno_aspirar: formLaudoCavaloInternoAspirar,
        cavalo_interno_hidratacao: formLaudoCavaloInternoHidratacao,
        cavalo_interno_motor: formLaudoCavaloInternoMotor,
        cavalo_externo: formLaudoCavaloExterno,
        cavalo_externo_agua_quente: formLaudoCavaloExternoAguaQuente,
        cavalo_externo_agua_fria: formLaudoCavaloExternoAguaFria,
        cavalo_cera: formLaudoCavaloCera,

        carreta_interno: formLaudoCarretaInterno,
        carreta_interno_agua_quente: formLaudoCarretaInternoAguaQuente,
        carreta_interno_agua_fria: formLaudoCarretaInternoAguaFria,
        carreta_externo: formLaudoCarretaExterno,
        carreta_externo_agua_quente: formLaudoCarretaExternoAguaQuente,
        carreta_externo_agua_fria: formLaudoCarretaExternoAguaFria,
        carreta_externo_jato_agua: formLaudoCarretaExternoJatoAgua,
        carreta_externo_boca_superior: formLaudoCarretaExternoBocaSuperior,
        carreta_externo_boca_lateral: formLaudoCarretaExternoBocaLateral,
        carreta_externo_embaixo: formLaudoCarretaExternoEmbaixo,
        carreta_externo_mangote: formLaudoCarretaExternoMangote,
        carreta_externo_lona: formLaudoCarretaExternoLona,

        secagem_manual_funcionario: formLaudoSecagemManualFunc || null,
        nome_motorista: formLaudoNomeMotorista || null,
        lavador_nome: formLaudoLavadorNome || null,
        lacres: cleanLacres,
        ultimas_cargas: cleanCargas,
        observacoes: finalObs,
        updated_at: new Date().toISOString()
      };

      if (laudoFormMode === 'create') {
        payload.id = crypto.randomUUID();
        payload.created_at = new Date().toISOString();
        payload.created_by = session?.user?.email || 'anon';

        let res = await fetch(`${SUPABASE_URL}/rest/v1/laudos_higienizacao`, {
          method: 'POST',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation'
          },
          body: JSON.stringify([payload])
        });

        if (!res.ok) {
          const errData = await res.json();
          if (errData.message && errData.message.includes('carreta_externo_mangote')) {
            const fallbackPayload = { ...payload };
            delete (fallbackPayload as any).carreta_externo_mangote;
            res = await fetch(`${SUPABASE_URL}/rest/v1/laudos_higienizacao`, {
              method: 'POST',
              headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
              },
              body: JSON.stringify([fallbackPayload])
            });
            if (!res.ok) {
              const errData2 = await res.json();
              throw new Error(errData2.message || 'Erro ao criar laudo.');
            }
          } else {
            throw new Error(errData.message || 'Erro ao criar laudo.');
          }
        }

        await fetch(`${SUPABASE_URL}/rest/v1/laudo_config?id=eq.config`, {
          method: 'PATCH',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ ultimo_numero: numeroLaudoToSave, updated_at: new Date().toISOString() })
        });

      } else if (laudoFormMode === 'edit' && selectedLaudo) {
        let res = await fetch(`${SUPABASE_URL}/rest/v1/laudos_higienizacao?id=eq.${selectedLaudo.id}`, {
          method: 'PATCH',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        if (!res.ok) {
          const errData = await res.json();
          if (errData.message && errData.message.includes('carreta_externo_mangote')) {
            const fallbackPayload = { ...payload };
            delete (fallbackPayload as any).carreta_externo_mangote;
            res = await fetch(`${SUPABASE_URL}/rest/v1/laudos_higienizacao?id=eq.${selectedLaudo.id}`, {
              method: 'PATCH',
              headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
                'Content-Type': 'application/json'
              },
              body: JSON.stringify(fallbackPayload)
            });
            if (!res.ok) {
              const errData2 = await res.json();
              throw new Error(errData2.message || 'Erro ao atualizar laudo.');
            }
          } else {
            throw new Error(errData.message || 'Erro ao atualizar laudo.');
          }
        }
      }

      await fetchSupabaseLaudos();
      await fetchSupabaseLaudoConfig();
      setLaudoFormMode('list');
      setSelectedLaudo(null);
    } catch (err: any) {
      console.error(err);
      setFormLaudoError(err.message || 'Erro ao salvar o laudo.');
    } finally {
      setFormLaudoSubmitting(false);
    }
  };

  const handleDeleteLaudo = async () => {
    if (!isDeletingLaudo) return;
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/laudos_higienizacao?id=eq.${isDeletingLaudo.id}`, {
        method: 'DELETE',
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });

      if (!res.ok) throw new Error('Erro ao excluir laudo do Supabase');

      await fetchSupabaseLaudos();
      setIsDeletingLaudo(null);
    } catch (err: any) {
      console.error(err);
      alert(err.message || 'Erro ao excluir laudo.');
    }
  };

  const handleSaveLaudoConfig = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormLaudoConfigSubmitting(true);
    setFormLaudoConfigError(null);
    setFormLaudoConfigSuccess(null);

    try {
      const ultimoNum = parseInt(formLaudoConfigUltimoNumero, 10);
      if (isNaN(ultimoNum) || ultimoNum < 0) {
        throw new Error('Por favor, informe um valor de sequência atual válido (igual ou maior que 0).');
      }

      const payload = {
        id: 'config',
        ultimo_numero: ultimoNum,
        updated_at: new Date().toISOString()
      };

      const res = await fetch(`${SUPABASE_URL}/rest/v1/laudo_config?on_conflict=id`, {
        method: 'POST',
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
          'Content-Type': 'application/json',
          'Prefer': 'resolution=merge-duplicates'
        },
        body: JSON.stringify([payload])
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.message || 'Erro ao salvar configuração.');
      }

      await fetchSupabaseLaudoConfig();
      setFormLaudoConfigSuccess('Configuração de sequência de laudos salva com sucesso!');
    } catch (err: any) {
      console.error(err);
      setFormLaudoConfigError(err.message || 'Erro ao salvar configuração.');
    } finally {
      setFormLaudoConfigSubmitting(false);
    }
  };

  // Funções CRUD para gerenciamento de Sequências de O.S.
  const handleOpenCreateOSSequence = () => {
    setFormSequenceAno('');
    setFormSequenceAtual('0');
    setFormSequenceError(null);
    setSelectedOSSequence(null);
    setOsSequenceFormMode('create');
  };

  const handleOpenEditOSSequence = (seq: OSSequencia) => {
    setSelectedOSSequence(seq);
    setFormSequenceAno(String(seq.ano));
    setFormSequenceAtual(String(seq.atual));
    setFormSequenceError(null);
    setOsSequenceFormMode('edit');
  };

  const handleSaveOSSequence = async (e: React.FormEvent) => {
    e.preventDefault();
    setFormSequenceSubmitting(true);
    setFormSequenceError(null);

    try {
      const anoNum = parseInt(formSequenceAno, 10);
      const atualNum = parseInt(formSequenceAtual, 10);

      if (isNaN(anoNum) || anoNum < 2000 || anoNum > 2100) {
        throw new Error('Por favor, informe um ano válido entre 2000 e 2100.');
      }
      if (isNaN(atualNum) || atualNum < 0) {
        throw new Error('Por favor, informe um valor de sequência atual válido (igual ou maior que 0).');
      }

      const payload: any = {
        ano: anoNum,
        atual: atualNum,
        updated_at: new Date().toISOString()
      };

      if (osSequenceFormMode === 'create') {
        payload.id = crypto.randomUUID();
        payload.created_at = new Date().toISOString();

        const res = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia`, {
          method: 'POST',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=representation'
          },
          body: JSON.stringify([payload])
        });

        if (!res.ok) {
          const errData = await res.json();
          if (errData.code === '23505') {
            throw new Error('Já existe uma sequência configurada para este ano!');
          }
          throw new Error(errData.message || 'Erro ao criar sequência.');
        }
      } else if (osSequenceFormMode === 'edit' && selectedOSSequence) {
        const res = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia?id=eq.${selectedOSSequence.id}`, {
          method: 'PATCH',
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
            'Content-Type': 'application/json'
          },
          body: JSON.stringify(payload)
        });

        if (!res.ok) {
          const errData = await res.json();
          throw new Error(errData.message || 'Erro ao atualizar sequência.');
        }
      }

      await fetchSupabaseOSSequencias();
      setOsSequenceFormMode('list');
      setSelectedOSSequence(null);
    } catch (err: any) {
      console.error(err);
      setFormSequenceError(err.message || 'Erro ao salvar a sequência.');
    } finally {
      setFormSequenceSubmitting(false);
    }
  };

  const handleDeleteOSSequence = async () => {
    if (!isExcluindoOSSequence) return;
    setIsDeletingOSSequence(true);

    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia?id=eq.${isExcluindoOSSequence.id}`, {
        method: 'DELETE',
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });

      if (!res.ok) throw new Error('Erro ao excluir sequência do Supabase');

      await fetchSupabaseOSSequencias();
      setIsExcluindoOSSequence(null);
    } catch (err: any) {
      console.error(err);
      alert(err.message || 'Erro ao excluir sequência.');
    } finally {
      setIsDeletingOSSequence(false);
    }
  };

  // Funções CRUD para gerenciamento de OS
  const getNextOSNumberForYear = async (year: number): Promise<string> => {
    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia?ano=eq.${year}&select=atual`, {
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });
      if (!res.ok) throw new Error('Erro ao obter sequência');
      const json = await res.json();
      const currentSeq = json && json[0] ? json[0].atual : 0;
      const nextNum = currentSeq + 1;
      return `OS-${String(nextNum).padStart(5, '0')}`;
    } catch (error) {
      console.error('Erro ao gerar sequenciamento automático:', error);
      return `OS-${Date.now().toString().slice(-5)}`;
    }
  };

  const handleOpenCreateOS = () => {
    const today = new Date();
    const offset = today.getTimezoneOffset();
    const localToday = new Date(today.getTime() - (offset * 60 * 1000));
    const nowStr = localToday.toISOString().slice(0, 16); // format: "YYYY-MM-DDTHH:mm"

    const year = localToday.getFullYear();
    setFormOSNumero('Gerando...');
    setFormOSData(nowStr);
    getNextOSNumberForYear(year).then(num => setFormOSNumero(num));

    setFormOSAvulso(false);
    setFormOSPessoaNome('');
    setFormOSPessoaId('');
    setFormOSVeiculoId('');
    setFormOSPlaca('');
    setFormOSPlacaCarreta1('');
    setFormOSPlacaCarreta2('');
    setFormOSPlacaCarreta3('');
    setFormOSMotorista('');
    setFormOSFrota('');
    setFormOSCentroCustoId('');
    setFormOSFormaPagamentoId('');
    setFormOSStatus('aberta');
    setFormOSObservacao('');
    setFormOSItems([]);
    setFormOSError(null);
    setSelectedOS(null);
    setHighlightAddItem(false);
    setOsFormMode('create');
  };

  const handleOpenEditOS = async (os: OrdemServico) => {
    setSelectedOS(os);
    setFormOSNumero(os.numero_os || '');
    setFormOSData(os.data_os ? os.data_os.slice(0, 16) : '');
    setFormOSPessoaNome(os.pessoa_nome || '');
    let personId = '';
    if (os.veiculo_id) {
      const v = supabaseVehicles.find(x => x.id === os.veiculo_id);
      if (v && v.pessoa_id) personId = v.pessoa_id;
    }
    if (!personId && os.pessoa_nome) {
      const p = supabaseData.find(x => x.nome_pessoa === os.pessoa_nome);
      if (p) personId = p.id;
    }
    setFormOSPessoaId(personId);
    setFormOSVeiculoId(os.veiculo_id || '');

    // Se não há ID de veículo e não há ID de pessoa, considera avulso
    const isAvulso = !os.veiculo_id && !personId;
    setFormOSAvulso(isAvulso);
    setFormOSPlaca(os.placa || '');
    setFormOSPlacaCarreta1(os.placa_carreta_1 || '');
    setFormOSPlacaCarreta2(os.placa_carreta_2 || '');
    setFormOSPlacaCarreta3(os.placa_carreta_3 || '');
    setFormOSMotorista(os.motorista || '');
    setFormOSFrota(os.frota || '');
    setFormOSCentroCustoId(os.centro_custo_id || '');
    setFormOSFormaPagamentoId(os.forma_pagamento_id || '');
    setFormOSStatus(os.status || 'aberta');
    setFormOSObservacao(os.observacao || '');
    setFormOSError(null);
    setHighlightAddItem(false);

    try {
      const res = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicoitem?ordem_servico_id=eq.${os.id}&select=*`, {
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });
      if (res.ok) {
        const items = await res.json();
        if (items && items.length > 0) {
          setFormOSItems(items);
        } else {
          setFormOSItems([]);
        }
      } else {
        setFormOSItems([]);
      }
    } catch (e) {
      console.error(e);
      setFormOSItems([]);
    }

    setOsFormMode('edit');
  };

  const handleSaveOS = async (e?: React.FormEvent, statusOverride?: 'aberta' | 'fechada') => {
    if (e) e.preventDefault();
    setFormOSSubmitting(true);
    setFormOSError(null);

    try {
      // Filtrar apenas itens que tenham descrição preenchida ou valor maior que zero
      const activeItems = formOSItems.filter(item => {
        const hasDesc = item.descricao && item.descricao.trim() !== '';
        const hasVal = item.valor !== undefined && item.valor > 0;
        return hasDesc || hasVal;
      });

      // Se o usuário iniciou o preenchimento de algum item (ou seja, colocou descrição ou valor),
      // então a descrição e o valor tornam-se obrigatórios para aquela inserção.
      for (const item of activeItems) {
        if (!item.descricao || item.descricao.trim() === '') {
          throw new Error('Por favor, preencha a descrição de todos os itens de serviços adicionados.');
        }
        if (item.valor === undefined || item.valor <= 0) {
          throw new Error(`Por favor, preencha um valor unitário válido para o item "${item.descricao}".`);
        }
      }

      const parsedItems = activeItems.map(item => {
        const qtde = parseFloat(String(item.qtde || 1));
        const valor = parseFloat(String(item.valor || 0));
        return {
          id: item.id && !String(item.id).startsWith('new-') ? item.id : crypto.randomUUID(),
          descricao: item.descricao!.trim(),
          qtde,
          valor,
          valor_total: qtde * valor
        };
      });

      const totalOSValue = parsedItems.reduce((acc, curr) => acc + curr.valor_total, 0);

      let pName = formOSPessoaNome;
      if (!pName && formOSPessoaId) {
        const p = supabaseData.find(x => x.id === formOSPessoaId);
        if (p) pName = p.nome_pessoa || 'Sem Nome';
      }

      const osId = osFormMode === 'create' ? crypto.randomUUID() : selectedOS!.id;

      const payloadOS: any = {
        id: osId,
        numero_os: formOSNumero || `OS-${osId.slice(-6)}`,
        data_os: formOSData ? new Date(formOSData).toISOString() : new Date().toISOString(),
        pessoa_nome: pName || 'Cliente',
        placa: formOSPlaca || null,
        placa_carreta_1: formOSPlacaCarreta1 || null,
        placa_carreta_2: formOSPlacaCarreta2 || null,
        placa_carreta_3: formOSPlacaCarreta3 || null,
        motorista: formOSMotorista || null,
        frota: formOSFrota || null,
        centro_custo_id: formOSCentroCustoId || null,
        forma_pagamento_id: formOSFormaPagamentoId || null,
        status: statusOverride || formOSStatus,
        valor_total: totalOSValue,
        observacao: formOSObservacao || null,
        veiculo_id: formOSVeiculoId || null,
        updated_at: new Date().toISOString()
      };

      if (osFormMode === 'create') {
        payloadOS.created_at = new Date().toISOString();
        payloadOS.created_by = session?.user?.id || null;

        const { error } = await supabase
          .from('ordemservicos')
          .insert([payloadOS]);
        if (error) throw error;
      } else {
        const { error } = await supabase
          .from('ordemservicos')
          .update(payloadOS)
          .eq('id', osId);
        if (error) throw error;
      }

      if (osFormMode === 'edit') {
        await supabase
          .from('ordemservicoitem')
          .delete()
          .eq('ordem_servico_id', osId);
      }

      const finalItems = parsedItems.map(item => ({
        id: item.id,
        ordem_servico_id: osId,
        descricao: item.descricao,
        qtde: item.qtde,
        valor: item.valor,
        valor_total: item.valor_total,
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
        created_by: session?.user?.id || null
      }));

      if (finalItems.length > 0) {
        const { error: itemsErr } = await supabase
          .from('ordemservicoitem')
          .insert(finalItems);
        if (itemsErr) throw itemsErr;
      }

      if ((statusOverride || formOSStatus) === 'fechada') {
        const checkEntrada = await fetch(`${SUPABASE_URL}/rest/v1/entradas?ordem_servico_id=eq.${osId}&select=id,data_entrada`, {
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
          }
        });
        const existingEntrada = await checkEntrada.json();

        const cc = supabaseCentroCusto.find(c => c.id === formOSCentroCustoId);
        const fp = supabaseFormaPagamento.find(f => f.id === formOSFormaPagamentoId);

        const payloadEntrada: any = {
          id: existingEntrada && existingEntrada.length > 0 ? existingEntrada[0].id : crypto.randomUUID(),
          ordem_servico_id: osId,
          data_entrada: existingEntrada && existingEntrada.length > 0 && existingEntrada[0].data_entrada
            ? existingEntrada[0].data_entrada
            : new Date().toISOString(),
          descricao_entrada: `Receita OS ${formOSNumero}`,
          valor: totalOSValue,
          centro_custo_id: formOSCentroCustoId || null,
          nome_centro_custo: cc ? (cc.nome_centro_custo || cc.descricao) : null,
          forma_pagamento_id: formOSFormaPagamentoId || null,
          descricao_forma_pagamento: fp ? fp.descricao : null,
          pessoa_id: formOSPessoaId || null,
          nome_pessoa: pName || 'Cliente',
          placa_veiculo: formOSPlaca || null,
          veiculo_id: formOSVeiculoId || null,
          updated_at: new Date().toISOString()
        };

        if (existingEntrada && existingEntrada.length > 0) {
          await supabase
            .from('entradas')
            .update(payloadEntrada)
            .eq('id', payloadEntrada.id);
        } else {
          payloadEntrada.created_at = new Date().toISOString();
          payloadEntrada.created_by = session?.user?.id || null;
          await supabase
            .from('entradas')
            .insert([payloadEntrada]);
        }
        await fetchSupabaseEntradas();
      }
      if (osFormMode === 'create') {
        const year = new Date(formOSData).getFullYear();
        if (!isNaN(year)) {
          const seqRes = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia?ano=eq.${year}&select=id,atual`, {
            headers: {
              'apikey': SUPABASE_ANON_KEY,
              'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
            }
          });
          if (seqRes.ok) {
            const seqJson = await seqRes.json();
            if (seqJson && seqJson[0]) {
              const seqId = seqJson[0].id;
              const seqAtual = seqJson[0].atual;
              await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia?id=eq.${seqId}`, {
                method: 'PATCH',
                headers: {
                  'apikey': SUPABASE_ANON_KEY,
                  'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
                  'Content-Type': 'application/json'
                },
                body: JSON.stringify({ atual: seqAtual + 1, updated_at: new Date().toISOString() })
              });
            } else {
              await fetch(`${SUPABASE_URL}/rest/v1/ordemservicosequencia`, {
                method: 'POST',
                headers: {
                  'apikey': SUPABASE_ANON_KEY,
                  'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`,
                  'Content-Type': 'application/json'
                },
                body: JSON.stringify([{ id: crypto.randomUUID(), ano: year, atual: 1, created_at: new Date().toISOString(), updated_at: new Date().toISOString() }])
              });
            }
          }
        }
      }

      await fetchSupabaseOrdemServicos();
      await fetchSupabaseOSSequencias();
      const isClosing = (statusOverride || formOSStatus) === 'fechada';
      if (osFormMode === 'create' || isClosing) {
        setOsFormMode('edit');
        setSelectedOS(payloadOS);
        setHighlightAddItem(isClosing ? false : true);
        if (isClosing) {
          setShowOSClosedPopup(true);
        }
      } else {
        setOsFormMode('list');
        setSelectedOS(null);
      }
    } catch (err: any) {
      console.error(err);
      setFormOSError(err.message || 'Erro ao salvar a ordem de serviço.');
    } finally {
      setFormOSSubmitting(false);
    }
  };

  const handleOpenPrintOSFromList = async (os: OrdemServico) => {
    setLoadingPrintOSData(true);
    try {
      let items: any[] = [];
      const resItems = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicoitem?ordem_servico_id=eq.${os.id}&select=*`, {
        headers: {
          'apikey': SUPABASE_ANON_KEY,
          'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
        }
      });
      if (resItems.ok) {
        const jsonItems = await resItems.json();
        if (jsonItems && jsonItems.length > 0) {
          items = jsonItems;
        }
      }

      if (items.length === 0) {
        items = [{
          qtde: 1,
          descricao: 'Serviço',
          valor: os.valor_total || 0,
          valor_total: os.valor_total || 0
        }];
      }

      const printData = {
        id: os.id,
        numero_os: os.numero_os || `OS-${os.id.slice(0, 6).toUpperCase()}`,
        pessoa_nome: os.pessoa_nome || '',
        pessoa_id: (os as any).pessoa_id || '',
        placa: os.placa || '',
        placa_carreta_1: os.placa_carreta_1 || '',
        placa_carreta_2: os.placa_carreta_2 || '',
        placa_carreta_3: os.placa_carreta_3 || '',
        motorista: os.motorista || '',
        frota: os.frota || '',
        forma_pagamento_id: os.forma_pagamento_id || '',
        forma_pagamento_desc: '',
        observacao: os.observacao || '',
        items
      };

      setActivePrintOSData(printData);
      setShowPrintOSModal(true);
    } catch (err) {
      console.error('Erro ao preparar impressão de OS:', err);
      alert('Erro ao carregar os dados da Ordem de Serviço para impressão.');
    } finally {
      setLoadingPrintOSData(false);
    }
  };

  const handleOpenPrintEntrada = async (entrada: Entrada) => {
    setLoadingPrintOSData(true);
    try {
      if (entrada.ordem_servico_id) {
        let os = supabaseOrdemServicos.find(o => o.id === entrada.ordem_servico_id);

        if (!os) {
          const resOS = await fetch(`${SUPABASE_URL}/rest/v1/ordemservico?id=eq.${entrada.ordem_servico_id}&select=*`, {
            headers: {
              'apikey': SUPABASE_ANON_KEY,
              'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
            }
          });
          if (resOS.ok) {
            const osList = await resOS.json();
            if (osList && osList.length > 0) {
              os = osList[0];
            }
          }
        }

        let items: any[] = [];
        const resItems = await fetch(`${SUPABASE_URL}/rest/v1/ordemservicoitem?ordem_servico_id=eq.${entrada.ordem_servico_id}&select=*`, {
          headers: {
            'apikey': SUPABASE_ANON_KEY,
            'Authorization': `Bearer ${session?.access_token || SUPABASE_ANON_KEY}`
          }
        });
        if (resItems.ok) {
          const jsonItems = await resItems.json();
          if (jsonItems && jsonItems.length > 0) {
            items = jsonItems;
          }
        }

        if (items.length === 0) {
          items = [{
            qtde: 1,
            descricao: entrada.descricao_entrada || 'Serviço Lavatório',
            valor: entrada.valor || 0,
            valor_total: entrada.valor || 0
          }];
        }

        const printData = {
          id: entrada.id,
          numero_os: os?.numero_os || `OS-${entrada.ordem_servico_id.slice(0, 6).toUpperCase()}`,
          pessoa_nome: os?.pessoa_nome || entrada.nome_pessoa || '',
          pessoa_id: os?.pessoa_id || entrada.pessoa_id || '',
          placa: os?.placa || entrada.placa_veiculo || '',
          placa_carreta_1: os?.placa_carreta_1 || '',
          placa_carreta_2: os?.placa_carreta_2 || '',
          placa_carreta_3: os?.placa_carreta_3 || '',
          motorista: os?.motorista || '',
          frota: os?.frota || '',
          forma_pagamento_id: os?.forma_pagamento_id || entrada.forma_pagamento_id || '',
          forma_pagamento_desc: entrada.descricao_forma_pagamento || '',
          observacao: os?.observacao || '',
          items
        };

        setActivePrintOSData(printData);
      } else {
        const printData = {
          id: entrada.id,
          numero_os: `REC-${entrada.id.slice(0, 6).toUpperCase()}`,
          pessoa_nome: entrada.nome_pessoa || 'Cliente Não Informado',
          pessoa_id: entrada.pessoa_id || '',
          placa: entrada.placa_veiculo || '',
          placa_carreta_1: '',
          placa_carreta_2: '',
          placa_carreta_3: '',
          motorista: '',
          frota: '',
          forma_pagamento_id: entrada.forma_pagamento_id || '',
          forma_pagamento_desc: entrada.descricao_forma_pagamento || 'Não Informada',
          observacao: 'Lançamento de Entrada / Receita',
          items: [{
            qtde: 1,
            descricao: entrada.descricao_entrada || 'Serviço Lavatório',
            valor: entrada.valor || 0,
            valor_total: entrada.valor || 0
          }]
        };

        setActivePrintOSData(printData);
      }
      setShowPrintOSModal(true);
    } catch (err) {
      console.error('Erro ao preparar impressão de OS da entrada:', err);
      alert('Erro ao carregar os dados para impressão da Ordem de Serviço.');
    } finally {
      setLoadingPrintOSData(false);
    }
  };

  const printHTMLContent = (htmlContent: string) => {
    let iframe = document.getElementById('lavajato-print-iframe') as HTMLIFrameElement;
    if (iframe) {
      try {
        document.body.removeChild(iframe);
      } catch (e) { }
    }

    iframe = document.createElement('iframe');
    iframe.id = 'lavajato-print-iframe';
    iframe.style.position = 'fixed';
    iframe.style.left = '-9999px';
    iframe.style.top = '-9999px';
    iframe.style.width = '1000px';
    iframe.style.height = '1000px';
    iframe.style.border = '0';
    iframe.style.opacity = '0.01';
    iframe.style.pointerEvents = 'none';
    document.body.appendChild(iframe);

    const doc = iframe.contentDocument || iframe.contentWindow?.document;
    if (!doc) {
      alert("Erro ao inicializar documento de impressão.");
      return;
    }

    doc.open();
    doc.write(htmlContent);
    doc.close();

    const doPrint = () => {
      try {
        if (iframe.contentWindow) {
          iframe.contentWindow.focus();
          iframe.contentWindow.print();
        }
      } catch (err) {
        console.error("Erro ao chamar print via iframe:", err);
        const printWin = window.open('', '_blank');
        if (printWin) {
          printWin.document.write(htmlContent);
          printWin.document.close();
          printWin.focus();
          printWin.print();
        }
      }
    };

    setTimeout(doPrint, 300);
  };

